import concurrent.futures,json,os,pathlib,subprocess,time,sys
root=pathlib.Path.cwd()
cache=pathlib.Path(os.environ['T166_RECEIPTS'])
files=json.loads((cache/'files.json').read_text())
env={**os.environ,'TOWER_CRANE_TEST_TMP':os.environ['TOWER_CRANE_TEST_TMP']}
burners=[subprocess.Popen(['nice','-n','15','node','-e','for (;;) Math.sqrt(Math.random());']) for _ in range(2)]
def measure(file):
 for label,tree in [('before',cache/'before'),('after',root)]:
  if not (tree/file).exists():continue
  sha=subprocess.check_output(['git','rev-parse','HEAD' if label=='after' else 'origin/main'],cwd=root,text=True).strip()
  for i in range(1,6):
   log=cache/(label+'-'+file.replace('/','_')+'-'+str(i)+'.log')
   receipt=log.with_suffix('.json')
   if receipt.exists():continue
   start=time.monotonic();load=os.getloadavg()
   with log.open('w') as out:
    result=subprocess.run(['node',str(tree/'test/run.js'),'--test-concurrency=1','--test-skip-pattern=publish its task branch',file],cwd=tree,env=env,stdout=out,stderr=subprocess.STDOUT,timeout=1800)
   row={'file':file,'label':label,'run':i,'sha':sha,'status':result.returncode,'wall_s':time.monotonic()-start,'load_before':load,'load_after':os.getloadavg(),'cpu_load_processes':2}
   receipt.write_text(json.dumps(row))
   print(label,file,i,result.returncode,flush=True)
try:
 with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
  for result in pool.map(measure,files):pass
finally:
 for p in burners:p.terminate()
 for p in burners:p.wait()
